/* Konsolenkost Shop-Widget (Artikelsuche), entpackt aus Beitragsinhalt */
(function(){
(function(){'use strict';function init(){document.querySelectorAll('.kk-nw').forEach(function(w){if(w.dataset.init)return;w.dataset.init='1';var grid=w.querySelector('.kk-nw-grid'),sort=w.querySelector('.kk-nw-s'),count=w.querySelector('.kk-nw-n'),status=w.querySelector('.kk-nw-status'),cards=Array.from(grid.children),filter='all';function update(){var list=cards.slice(),n=0;if(sort.value==='asc')list.sort(function(a,b){return Number(a.dataset.p)-Number(b.dataset.p);});if(sort.value==='desc')list.sort(function(a,b){return Number(b.dataset.p)-Number(a.dataset.p);});if(sort.value==='name')list.sort(function(a,b){return a.querySelector('strong').textContent.localeCompare(b.querySelector('strong').textContent,'de');});list.forEach(function(c){grid.appendChild(c);var show=(filter==='all'||c.dataset.c===filter)&&c.dataset.unavailable!=='1';c.style.display=show?'flex':'none';if(show)n++;});count.textContent=n+' Artikel'+(n?'':' – bitte einen anderen Filter wählen.');grid.scrollLeft=0;}w.querySelectorAll('button[data-f]').forEach(function(b){b.addEventListener('click',function(){filter=b.dataset.f;w.querySelectorAll('button[data-f]').forEach(function(x){x.setAttribute('aria-pressed',String(x===b));x.style.background=x===b?'#14232d':'#fff';x.style.color=x===b?'#fff':'#14232d';});update();});});sort.addEventListener('change',update);cards.forEach(function(c){var im=c.querySelector('img');im.addEventListener('error',function(){c.dataset.unavailable='1';update();});});update();function request(u,o){var ctl=new AbortController(),timer=setTimeout(function(){ctl.abort();},12000);return fetch(u,Object.assign({},o||{},{signal:ctl.signal})).then(function(r){if(!r.ok)throw new Error('Abruf fehlgeschlagen');return r;}).finally(function(){clearTimeout(timer);});}window.kkNwPublicKey=window.kkNwPublicKey||request('https://cdn02.plentyone.com/xp4oxtd91bsc/plugin/509/konsolenkostplugininstantsearch/js/dist/konsolenkost-autoComplete.min.js').then(function(r){return r.text();}).then(function(t){var m=t.match(/,s="([^"]+)",u="item_group"/);if(!m)throw new Error('Suchkonfiguration geändert');return m[1];}).catch(function(e){window.kkNwPublicKey=null;throw e;});window.kkNwPublicKey.then(function(key){var ids=w.dataset.ids.split(',').filter(function(v){return /^\d+$/.test(v);});if(!ids.length)throw new Error('Keine Artikelauswahl');var p=new URLSearchParams({q:'*',preset:'webshop-search',per_page:'100',filter_by:'availability_id:=1 && items.id:=['+ids.join(',')+']'});return request('https://articles-search-new.konsolenkost-tools.de/typesense/collections/item_group/documents/search?'+p,{headers:{'X-TYPESENSE-API-KEY':key}});}).then(function(r){return r.json();}).then(function(data){if(!Array.isArray(data.hits))throw new Error('Ungültige Suchantwort');var available={};data.hits.forEach(function(h){var d=h.document;if(d.availability_id!==1||/18#/.test(String(d.usk||'')))return;(d.items||[]).forEach(function(it){if(it.availability_id===1&&Number.isFinite(Number(it.price))&&Number(it.price)>0)available[String(it.item_id)]=it;});});cards.forEach(function(c){var it=available[c.dataset.id];c.dataset.unavailable=it?'0':'1';if(it){c.dataset.p=String(it.price);var price=c.querySelector('.kk-nw-price');price.textContent=Number(it.price).toLocaleString('de-DE',{style:'currency',currency:'EUR'});price.hidden=false;}});w.dataset.live='1';status.textContent='Preis und Lieferbarkeit live geprüft. Maßgeblich ist das Angebot im Shop.';update();}).catch(function(){cards.forEach(function(c){c.dataset.unavailable='1';});status.textContent='Die Lieferbarkeit lässt sich gerade nicht prüfen. Bitte die Shop-Suche nutzen.';update();});});}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init();})();
})()
